CREATE OR REPLACE FUNCTION public.admin_account_choices() RETURNS TABLE(user_id uuid,email text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Нет доступа'; END IF; RETURN QUERY SELECT u.id,u.email::text FROM auth.users u ORDER BY u.created_at; END $$;
REVOKE ALL ON FUNCTION public.admin_account_choices() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_account_choices() TO authenticated;
CREATE OR REPLACE FUNCTION public.validate_tax_margin() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.variant_wholesale WHERE minimum_margin_percent+NEW.payment_tax_percent >= 100) THEN RAISE EXCEPTION 'Налог/комиссия и минимальная маржа должны в сумме быть меньше 100%%'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_tax_margin BEFORE UPDATE OF payment_tax_percent ON public.site_settings FOR EACH ROW EXECUTE FUNCTION public.validate_tax_margin();
CREATE OR REPLACE FUNCTION public.validate_dealer_approval() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.approved AND NOT EXISTS(SELECT 1 FROM public.wholesale_leads WHERE id=NEW.lead_id AND status='approved') THEN RAISE EXCEPTION 'Сначала одобрите заявку'; END IF; IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=NEW.user_id) THEN RAISE EXCEPTION 'Аккаунт не найден'; END IF; IF NEW.manual_level_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.wholesale_levels WHERE id=NEW.manual_level_id AND manual_only) THEN RAISE EXCEPTION 'Выберите ручной уровень'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_dealer_approval BEFORE INSERT OR UPDATE ON public.dealer_accounts FOR EACH ROW EXECUTE FUNCTION public.validate_dealer_approval();
ALTER TABLE public.products ADD CONSTRAINT automatic_pricing_reference_required CHECK (NOT auto_pricing OR (reference_volume_ml IS NOT NULL AND reference_price IS NOT NULL));